try{lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi';const saved=JSON.parse(localStorage.getItem(KEY));const restored=restoreGame(saved?.game);const recoveredHub=restoreHub(saved?.hub);if(restored&&recoveredHub&&(!saved.hub.active||saved.hub.active.id===restored.runId)){state=restored;hub=recoveredHub;if(['challenge','practice'].includes(saved.mode))selectedMode=saved.mode;}else{const legacy=restoreGame(JSON.parse(localStorage.getItem('moneyLabBoard.v1')));if(legacy){state=legacy;if(state.started&&state.phase!=='finished'){state.started=false;beginRun(hub,state,runId(),'practice');}}}}catch{storageAvailable=false;}

