copy.vi.rulesList[2]='Trước mỗi lượt, chuyển tiền giữa tiền mặt và dự phòng hoặc mua quỹ ML-100 hư cấu. Ô Cơ hội có Apple (AAPL), Coca-Cola (KO), BTC, ETH, bất động sản trả góp, cửa hàng thời trang và quán ăn. Giá và tỷ lệ đều giả lập.';
copy.vi.rulesList[3]='Ô Bất ngờ có cả khoản thu một lần (quà, thừa kế, giải thưởng), chi phí thiết yếu và chi tiêu tự chọn có thể bỏ qua: iPhone, đổi xe, du lịch. Chi phí thiết yếu dùng dự phòng, tiền mặt rồi bán tài sản có thanh khoản. Món tự chọn chỉ dùng tiền mặt; giá trị bán lại chưa được tính.';
copy.vi.rulesList[4]='Mỗi nhóm tài sản có tỷ lệ biến động riêng tại ô Thị trường. Vốn bất động sản và kinh doanh khóa bán suốt ván. Bất động sản $4.500 cần trả trước $2.700, còn nợ $1.800 trả $300/tháng trong 6 lượt tiếp theo. Mỗi kỳ trả dùng tiền mặt trước, rồi dự phòng và tài sản thanh khoản; thiếu tiền thì ván kết thúc. Nợ cuối ván vẫn trừ khỏi tài sản ròng. Có định giá và phân phối tiền mặt từ bất động sản/kinh doanh hằng tháng; chưa tính lãi, thuế hay cổ tức cổ phiếu.';
copy.vi.rulesList.push('36 câu kiến thức được rút không lặp trong một ván, kể cả sau khi tải lại hay đổi ngôn ngữ. Vị trí đáp án đúng thay đổi. Chi tiêu tự chọn cộng điểm trải nghiệm riêng; không tăng điểm tài chính. Món đồ và trải nghiệm không có giá trị bán lại trong mô hình.');
copy.en.rulesList[2]='Before each turn, move cash into or out of reserves, or buy the fictional ML-100 fund. Opportunity spaces offer Apple (AAPL), Coca-Cola (KO), BTC, ETH, installment property, a fashion store or a restaurant. All prices and rates are fictional.';
copy.en.rulesList[3]='Unexpected spaces include one-off gifts, inheritances and prizes, essential bills and optional spending you can decline: an iPhone, a car upgrade or a holiday. Essential bills use reserves, cash, then liquid asset sales. Optional purchases use cash only; resale value is not modeled.';
copy.en.rulesList[4]='Market events apply different rates to each asset category. Property and business capital are locked for the entire game. A $4,500 property share requires $2,700 down plus $1,800 debt, paid at $300/month for the next 6 turns. Installments use cash, reserves, then liquid assets; inability to pay ends the game. Outstanding debt is deducted from final net worth. Monthly valuations and property/business cash distributions are modeled; interest, taxes and stock dividends are not.';
copy.en.rulesList.push('36 knowledge questions are drawn without repeats in a game, even after reloading or switching languages. Correct-answer positions vary. Optional purchases add separate enjoyment points, not financial-score points. No resale value is modeled for these purchases.');
const t=k=>copy[lang][k],money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v),signed=v=>(v>0?'+':'')+money(v);
const coords=[[1,1],[1,2],[1,3],[1,4],[1,5],[2,5],[3,5],[4,5],[5,5],[5,4],[5,3],[5,2],[5,1],[4,1],[3,1],[2,1]];
const colors={start:'#5f8061',opportunity:'#558c79',expense:'#b7795f',learn:'#8c84a5',market:'#6c91a0',salary:'#b39b5e'};
function persist(){if(account)return;try{localStorage.setItem(KEY,JSON.stringify({game:state,hub,mode:selectedMode}));}catch{storageAvailable=false;}}
function levelCopy(){const l=levelOf(state),cash=money(l.cash),reserve=money(l.reserve),income=money(l.salary),living=money(l.living),initial=money(l.cash+l.reserve);Object.assign(copy.vi,{welcomeText:`Bạn có ${initial}: ${cash} tiền mặt và ${reserve} dự phòng. Mức ${l.vi[0]} có lương cơ bản ${income}, sinh hoạt ${living}/tháng.`,readyText:`Lương cơ bản ${income}, sinh hoạt ${living}/tháng, chưa gồm trả góp. ${l.vi[2]}`,receiptIncome:`Lương +${money(state.pending?.monthly?.salary??state.last?.monthly?.salary??incomeAt(state,Math.min(12,state.month+1)))}`,receiptExpense:`Sinh hoạt −${living}`});Object.assign(copy.en,{welcomeText:`Start with ${initial}: ${cash} cash and ${reserve} reserve. ${l.en[0]} has base salary ${income} and ${living} monthly living costs.`,readyText:`Base salary ${income}, living costs ${living}/month before installments. ${l.en[2]}`,receiptIncome:`Salary +${money(state.pending?.monthly?.salary??state.last?.monthly?.salary??incomeAt(state,Math.min(12,state.month+1)))}`,receiptExpense:`Living costs −${living}`});copy.vi.rulesList[0]=`Mức ${l.vi[0]} bắt đầu với ${initial}: ${cash} tiền mặt và ${reserve} dự phòng. Mục tiêu là hoàn thành 12 tháng mà vẫn thanh toán được nghĩa vụ.`;copy.en.rulesList[0]=`${l.en[0]} starts with ${initial}: ${cash} cash and ${reserve} reserve. Aim to complete 12 months while meeting required payments.`;copy.vi.rulesList[1]=`Mỗi lượt là một tháng: lương cơ bản ${income}, sinh hoạt ${living}. ${l.vi[2]} Lượt đầu là Cơ hội; tối đa 2 ô Kiến thức mỗi chặng.`;copy.en.rulesList[1]=`One turn is one month: base salary ${income}, living costs ${living}. ${l.en[2]} The first draw offers Opportunity; at most two Knowledge visits per stage.`;copy.vi.rulesList[5]=`Điểm: tài sản /40 (mốc ${money(wealthBenchmark(state))}), dự phòng /35 (3 tháng sinh hoạt: ${money(l.living*3)}), thanh khoản /15 (trừ 5 mỗi lần buộc bán), kiến thức /10 (tỷ lệ đúng). Điểm từng cấp dùng mốc riêng; không so trực tiếp giữa các cấp.`;copy.en.rulesList[5]=`Score: wealth /40 (${money(wealthBenchmark(state))} benchmark), reserve /35 (3 months of costs: ${money(l.living*3)}), liquidity /15 (minus 5 per forced sale), knowledge /10 (correct-answer rate). Benchmarks differ by level; compare within a level.`;}
function chrome(){levelCopy();document.documentElement.lang=lang;['version','eyebrow','headline','subtitle','monthLabel','boardHint','saveLabel','historyTitle','disclaimer','classicLink','resetTitle','resetText','confirmReset','cancelReset','closeRules'].forEach((id)=>{const keys={monthLabel:'month',boardHint:'hint',saveLabel:storageAvailable?'saved':'notSaved',historyTitle:'history',classicLink:'classic',closeRules:'close',cancelReset:'cancel'};$('#'+id).textContent=t(keys[id]||id);});$('#resetText').textContent=(lang==='vi'?'Ván đang lưu sẽ được thay thế. ':'This replaces your saved game. ')+(hub.active?.bond?(lang==='vi'?`Bỏ ván sẽ mất ${hub.active.bond} HUB giả lập đang cam kết.`:`Abandoning forfeits the ${hub.active.bond} simulated HUB committed to this run.`):(lang==='vi'?'Tiến độ và HUB trong Hub được giữ lại.':'Your Hub progress and HUB are retained.'));$('#rulesButton').textContent=t('rules');$('#resetButton').textContent=lang==='vi'?'Chặng mới · giữ HUB':'New stage · keep HUB';['vi','en'].forEach(l=>$('#'+l).classList.toggle('active',lang===l));$('#rulesContent').innerHTML=guideHTML(lang,state);$('#rulesButton').textContent=lang==='vi'?'Giới thiệu & Luật chơi':'About & Rules';$('#boardHint').textContent=lang==='vi'?'1 lượt = 1 tháng · Gieo 2 lựa chọn, chọn 1':'1 turn = 1 month · Roll 2 options, choose 1';$('#quickGuide').innerHTML=quickGuide(lang);;}
function renderHub(){const vi=lang==='vi',l=levelOf(state);$('#hub').innerHTML=`${tokenRoadmap(lang)}<div class="hub-top"><div><p class="eyebrow">MONEY LAB / ${vi?'CHIẾN DỊCH LIÊN TỤC':'CONTINUOUS CAMPAIGN'}</p><h2>${account?(vi?'HUB của bạn.<br>Tiến trình theo ví.':'Your HUB.<br>Progress with your wallet.'):(vi?'80 HUB khởi đầu.<br>Thắng để tiến xa hơn.':'Start with 80 HUB.<br>Win your way forward.')}</h2><p class="hub-note">${vi?'HUB là token giả lập trong game, không đổi tiền thật. Thắng Dễ mở Trung bình; thắng Trung bình mở Khó. Hết HUB thì quay về Dễ để tích lũy.':'HUB is fictional game credit, not redeemable money. Win Easy to unlock Medium, then win Medium to unlock Hard. Rebuild on Easy when funds run low.'}</p></div><div class="lab-wallet"><span class="lab-coin">H</span><div><small>${vi?'HUB khả dụng':'Available HUB'}</small><strong>${hub.balance}<em> HUB</em></strong></div><div class="lab-wallet-meta"><span>${vi?'Đang cam kết':'Committed'}<b>${hub.active?.bond||0}</b></span><span>${vi?'Đã thưởng':'Earned'}<b>+${hub.earned}</b></span><span>${vi?'Đã mất':'Lost'}<b>−${hub.lost}</b></span></div></div></div><div class="hub-setup"><div class="campaign-path">${Object.values(LEVELS).map(l=>`<span class="${unlocked(hub,l.id)?'open':'locked'}">${l[lang][0]} · ${hub.wins[l.id]} ${vi?'trận thắng':'wins'} ${unlocked(hub,l.id)?'✓':'🔒'}</span>`).join('<b>→</b>')}</div>${!state.started?`<div class="level-grid">${Object.values(LEVELS).map(l=>`<button data-level="${l.id}" class="level-card ${l.id===state.difficulty?'selected':''}" ${chainBusy||!unlocked(hub,l.id)?'disabled':''}><strong>${l[lang][0]}</strong><small>${l[lang][2]}</small><span class="level-bond">${l.bond} HUB · ${vi?'Thắng':'Win'} ≥ ${l.target}/100 · ${vi?'Thưởng từ':'Reward from'} ${l.rewardBase} HUB${!unlocked(hub,l.id)?` · ${vi?'Chưa mở khóa':'Locked'}`:''}</span></button>`).join('')}</div>`:`<div class="active-level"><b>${l[lang][0]} · ${vi?'Chặng':'Stage'} ${hub.runs+Number(state.phase!=='finished')}</b><span>${vi?'Mục tiêu':'Goal'}: 12 ${vi?'tháng, không thiếu thanh toán và':'months, no unpaid costs and'} ≥${l.target}/100</span><button data-action="reset" class="text-button" ${chainBusy?'disabled':''}>${vi?'Đổi cấp / Bỏ chặng':'Change level / Abandon stage'}</button></div>`}<p class="hub-fine">${vi?'Mỗi lần thắng đều nhận HUB: thưởng cơ bản + thưởng theo điểm. Một kết quả chỉ trả thưởng một lần; chơi lại phải hoàn thành chặng mới. Mỗi chặng 12 tháng có ngân sách riêng; HUB và lịch sử chiến dịch được giữ liên tục.':'Every winning stage pays HUB: base reward plus a score bonus. Each result settles once; replays require a new completed stage. Each 12-month stage has its own starting budget; HUB and campaign history continue.'}</p><p><a class="duel-link" href="./online.html">${vi?'Duet / Nhóm online · chơi khác thiết bị →':'Online Duet / Group · separate devices →'}</a></p><details><summary>${vi?'Luật HUB và lịch sử chặng':'HUB rules and stage history'}</summary><p>${vi?'Khởi tạo 80 HUB. Dễ miễn phí, Trung bình cam kết 40, Khó 80. Thắng hoàn cam kết và nhận thưởng; thua hoặc bỏ chặng mất phần cam kết. Các mức cao không có đường vào luyện tập miễn phí.':'Start with 80 HUB. Easy is free, Medium commits 40, Hard 80. Winning returns the commitment plus rewards; losing or abandoning forfeits it. Higher levels have no free-practice bypass.'}</p>${hub.journey.map(r=>`<div class="history-row"><span>${LEVELS[r.level][lang][0]}</span><strong>${r.points}/100 · ${r.won?(vi?'Thắng':'Won'):(vi?'Chưa đạt':'Not cleared')}</strong><em>${r.net>=0?'+':''}${r.net} HUB</em></div>`).join('')}${hub.ledger.some(r=>r.kind==='rebase')?`<p>${vi?'Số dư bản cũ đã được điều chỉnh một lần từ mức cấp 300 xuống 80 HUB; phần thưởng và khoản mất đã có được giữ lại.':'The old 300-HUB welcome grant was rebased once to 80; existing earned rewards and losses were retained.'}</p>`:''}</details></div>`;}
function labSettlement(){const r=state.labResult;if(!r)return '';const vi=lang==='vi';return `<div class="lab-settlement"><h3>${r.won?(vi?'Chặng hoàn thành!':'Stage cleared!'):(vi?'Chưa vượt qua chặng':'Stage not cleared')}</h3><p>${vi?'Hoàn cam kết':'Returned'}: ${r.refund} HUB · ${vi?'Thưởng chặng':'Stage reward'}: +${r.reward} HUB · ${vi?'Mất':'Lost'}: ${r.loss} HUB</p><div class="continuation">${Object.values(LEVELS).filter(l=>unlocked(hub,l.id)).map(l=>button(`${vi?'Tiếp tục':'Continue'} · ${l[lang][0]} · ${l.bond} HUB`,'stage-'+l.id,l.id===state.difficulty,hub.balance<l.bond)).join('')}</div><small>${vi?'Bấm để vào thẳng chặng kế tiếp, không cần tạo lại hồ sơ hay về menu.':'Enter the next stage directly without resetting your profile or returning to a menu.'}</small></div>`;}

function stats(){const data=[['net',netWorth(state),'netHint'],['cash',state.cash,'cashHint'],['reserve',state.reserve,'reserveHint'],['assets',state.investments,'assetsHint']];$('#stats').innerHTML=data.map(([label,value,hint])=>`<div class="stat"><label>${t(label)}</label><strong>${money(value)}</strong><small>${t(hint)}</small></div>`).join('');$('#month').textContent=`${String(state.month).padStart(2,'0')} / 12`;$('#monthProgress').innerHTML=Array.from({length:12},(_,i)=>`<i class="${i<state.month?'done':''}"></i>`).join('');}
function board(){let tiles=TILES.map((type,i)=>`<div class="tile ${i===state.position?'active':''}" style="grid-row:${coords[i][0]};grid-column:${coords[i][1]};--tile-color:${colors[type]}" ${i===state.position?'aria-current="location"':''}><span class="tile-num">${String(i+1).padStart(2,'0')}</span><span class="game-art game-art-${type}" aria-hidden="true"></span><span class="tile-label">${t('tile')[type]}</span>${i===state.position?'<span class="pawn" aria-label="Player">F</span>':''}</div>`).join('');$('#board').innerHTML=tiles+`<div class="board-center"><span class="center-kicker">THE FINANCIAL PLAYGROUND</span><img class="board-world" src="./assets/money-town-v1.png" alt="" loading="lazy" decoding="async" width="360" height="360"><div class="center-title">MONEY LAB</div><span class="center-tagline">${t('tagline')}</span><div class="dice" aria-label="Dice ${state.dice||''}">${state.dice?['','⚀','⚁','⚂','⚃','⚄','⚅'][state.dice]:'◇'}</div></div>`;}
function management(){const enabled=state.started&&state.phase==='ready'&&!state.route&&!rolling&&!chainBusy;const actions=[['reserve','toReserve',state.cash>=500],['release','release',state.reserve>=500],['invest','invest',state.cash>=1000&&state.gate.OUT0===1&&chainReady],['sell','sell',sellable(state)>0]];$('#management').innerHTML=`<div class="management-title">${t('manage')}</div><div class="management-actions">${actions.map(([action,label,ok])=>`<button data-manage="${action}" ${enabled&&ok?'':'disabled'}>${t(label)}</button>`).join('')}</div><div class="portfolio"><h3>${t('portfolio')}</h3>${state.positions.some(p=>p.value>0)?state.positions.filter(p=>p.value>0).map(p=>`<div class="position"><div><strong>${p.id==='legacy'?CATEGORY_NAMES[lang].legacy:opportunity(p.id)[lang][0]}</strong><small>${CATEGORY_NAMES[lang][p.kind]} · ${t(p.locked?'locked':'liquid')}</small>${p.debt>0?`<small>${t('debt')}: ${money(p.debt)} · ${money(Math.min(p.payment,p.debt))}/${lang==='vi'?'tháng':'month'}</small>`:''}</div><b>${money(p.value)}</b></div>`).join(''):`<p>${t('emptyPortfolio')}</p>`}<div class="portfolio-summary"><span>${t('debt')}<b>${money(debt(state))}</b></span><span>${t('installment')}<b>${money(monthlyPayment(state))}</b></span><span>${t('joy')}<b>${state.enjoyment}</b></span></div>${state.positions.some(p=>p.locked)?`<small>${t('noLiquid')}</small>`:''}</div>`;}

const button=(label,action,secondary=false,disabled=false)=>`<button class="${secondary?'secondary':'primary'}" data-action="${action}" ${disabled||chainBusy?'disabled':''}>${label}</button>`;
function resultText(r){if(r.windfall)return `${surprise(r.eventId)[lang][0]} · +${money(r.windfall)}`;if(r.type==='opportunity')return `${r.eventId?opportunity(r.eventId)[lang][0]:t('tile').opportunity} · ${r.choice==='buy'?`${t('investNow')}: ${money(r.bought)}`:t('skipped')}`;if(r.type==='learn')return r.review?t('quizDone'):t(r.correct?'correct':'incorrect');if(r.type==='expense'&&r.eventId==='living-shortfall')return lang==='vi'?'Không đủ tiền trả sinh hoạt':'Unable to pay living costs';if(r.type==='expense'){const e=surprise(r.eventId);if(e?.optional)return `${e[lang][0]} · ${r.choice==='spend'?`${t('spent')} ${money(r.optionalCost)} · +${r.joy} ${t('joy')}`:t('declined')}`;return `${e?e[lang][0]:t('installmentsPaid')} · ${t('paid')}`;}if(r.type==='market')return `${t('marketResult')} ${signed(r.change)}`;return `${r.incomeId?sideJob(r.incomeId)[lang][0]:t('bonusResult')} · ${money(r.bonus)}`;}

function decision(){
 let html='';
 if(!state.started){html=`<span class="card-kicker">${t('welcomeKicker')}</span><h2>${t('welcomeTitle')}</h2><p>${t('welcomeText')}</p>${button((lang==='vi'?'Bắt đầu · ':'Start · ')+(selectedMode==='practice'?(lang==='vi'?'Luyện tập miễn phí':'Free practice'):(levelOf(state).bond?`${levelOf(state).bond} HUB`:lang==='vi'?'Miễn phí':'Free')),'start',false,selectedMode==='challenge'&&(hub.balance<levelOf(state).bond||!unlocked(hub,state.difficulty)))}`;}
 else if(state.phase==='finished'){const sc=score(state);html=`<span class="card-kicker">${t('endKicker')}</span><h2>${t(state.shortfall>0?'endEarly':'endTitle')}</h2><div class="score"><strong>${sc.total}</strong><small>/ 100 · ${t('score')}</small></div><p>${t('endText')}</p><div class="score-grid"><div>${t('net')}<b>${money(netWorth(state))}</b></div><div>${t('endingReserve')}<b>${(state.reserve/levelOf(state).living).toFixed(1)}</b></div><div>${t('forcedCount')}<b>${state.forcedSales}</b></div><div>${t('knowledge')}<b>${state.correctAnswers} / ${state.answered}</b></div></div><p class="score-breakdown">${t('scoreDetails')}<br>${sc.wealth} + ${sc.buffer} + ${sc.liquidity} + ${sc.knowledge} = ${sc.total}</p>${state.shortfall>0?`<p class="warning">${t('unpaid')} ${money(state.shortfall)}</p>`:''}<div class="event-detail">${t('optionalTotal')}: ${money(state.optionalSpent)} · ${t('joy')}: ${state.enjoyment}<br><small>${t('joyNote')}</small></div>${labSettlement()}`;}
 else if(state.phase==='ready'&&state.route){html=`<span class="card-kicker">${lang==='vi'?'CHỌN ĐƯỜNG ĐI':'CHOOSE YOUR ROUTE'}</span><h2>${lang==='vi'?'Tháng tới, bạn chọn ô nào?':'Where will you land next month?'}</h2><p>${lang==='vi'?'Lượt gieo đã chốt một nhóm sự kiện và hai ô cùng nhóm. Đọc vốn cần, khả năng bán và nợ trước khi chọn. Nội dung đầy đủ mở sau khi chọn. Ví dụ Cơ hội ô 2 hoặc ô 11; không mất HUB để chọn.':'The roll locks one event category and two spaces in that category. Compare entry cash, liquidity and debt before choosing; the full scenario opens afterward, e.g. Opportunity at space 2 or 11. Selection costs no HUB.'}</p>${routeChoicesHTML(state,lang,'data-action','route-',chainBusy||rolling)}<p class="result-note">${lang==='vi'?'Chưa thu lương hoặc trừ chi phí tháng mới. Chọn đường để tiếp tục; không thể gieo lại bằng cách tải trang.':'Next-month income and costs have not applied yet. Choose to proceed; reloading does not reroll.'}</p>`;}
 else if(state.phase==='ready'){html=`<span class="card-kicker">${state.last?t('resultKicker'):t('readyKicker')}</span><h2>${state.last?t('tile')[state.last.type]:t('readyTitle')}</h2>${state.last?`<p>${resultText(state.last)}</p>${detail(state.last)}`:`<p>${t('readyText')}</p>`}${button(t(rolling?'rolling':'roll'),'roll',false,rolling)}<div class="monthly-receipt"><span>${t('receiptIncome')}</span><span>${t('receiptExpense')}</span></div>`;}
 else{const {type,variant:v}=state.pending;html=`<div class="event-art" aria-hidden="true">${type==='market'&&v!==1?'<img src="./assets/money-town-v1.png" alt="" width="138" height="138" decoding="async"><span class="market-mood">↘</span>':`<span class="game-art game-art-${type}"></span>`}</div><span class="card-kicker">${t('event')} ${String(state.month).padStart(2,'0')} / ${t('tile')[type]}</span>`;
 if(type==='opportunity'){const o=opportunity(state.pending.eventId);html+=`<h2>${o[lang][0]}</h2><p>${o[lang][1]}</p><span class="amount">${money(o.cost)}</span><p class="result-note">${t('purchaseCost')} · ${CATEGORY_NAMES[lang][o.kind]} · ${t(['property','fashion','food'].includes(o.kind)?'locked':'liquid')}</p>${button(t('investNow'),'buy',false,state.cash<o.cost||state.gate.OUT0===0||!chainReady)}${button(t('decline'),'skip',true)}<p class="result-note">${t('modelNote')}</p>${state.cash<o.cost||state.gate.OUT0===0||!chainReady?`<p class="result-note">${t('noCash')}</p>`:''}`;}
 else if(type==='expense'){const e=surprise(state.pending.eventId);html+=`${e.optional?`<span class="choice-tag">${t('optional')}</span>`:''}<h2>${e[lang][0]}</h2><span class="amount">${e.income?'+':'−'}${money(e.income|| (e.optional?e.cost:essentialCost(state,e.cost)))}</span><p>${e[lang][1]}</p>${e.optional?`${button(t('spendNow'),'spend',false,state.cash<e.cost)}${button(t('decline'),'skip',true)}<p class="result-note">${t('optionalNote')} (+${e.joy} ${t('joy')})</p>${state.cash<e.cost?`<p class="warning">${t('noOptionalCash')}</p>`:''}`:`<p>${e.income?(lang==='vi'?'Khoản thu một lần sẽ vào tiền mặt.':'This one-off receipt goes to cash.'):t('expenseText')}</p>${button(e.income?(lang==='vi'?'Nhận khoản tiền':'Receive funds'):t('pay'),'pay')}`}`;}
 else if(type==='market'){const story=marketStory(state.pending.marketId),kinds=[...new Set(state.positions.filter(p=>p.value>0).map(p=>p.kind))];html+=`<h2>${story?story[lang][0]:t('marketTitle')[v]}</h2><p>${story?story[lang][1]:t('marketText')}</p>${kinds.length?`<div class="event-detail">${t('marketBreakdown')}<br>${kinds.map(k=>`${CATEGORY_NAMES[lang][k]}: ${Number((marketRate(state,story?.rates[k]??MARKET_RATES[k][v])*100).toFixed(2))}%`).join('<br>')}</div>`:`<div class="event-detail">${t('marketEmpty')}</div>`}${button(t('continue'),'continue')}`;}
 else if(type==='learn'){const item=question(state.pending.questionId);if(!item)html+=`<h2>${t('learnTitle')}</h2><p>${t('quizDone')}</p>${button(t('continue'),'continue')}`;else{const q=item[lang],order=state.pending.answerOrder;html+=`<span class="choice-tag">${t('quizProgress')} ${state.usedQuestions.length} / ${questionPool(state).length}</span><h2>${t('learnTitle')}</h2><p>${q[0]}</p>${[0,1].map(i=>button(q[i===order?1:2],`answer-${i}`,true)).join('')}<p class="result-note">${t('learnText')}</p>`;}}
 else html+=`${type==='salary'?jobHTML(state.pending,lang):`<h2>${t('startTitle')}</h2><span class="amount">+$300</span><p>${t('bonusText')}</p>`}${button(t('continue'),'continue')}`;
 html+=`${monthlyHTML(state.pending,lang)}${installmentDetail(state.pending)}<div class="monthly-receipt"><span>${t('receiptIncome')}</span><span>${t('receiptExpense')}</span></div>`;}
 $('#decision').innerHTML=html;
}
function installmentDetail(r){const extra=r?.monthly?.surcharge||0;const extraNote=extra?`<div class="income-shock">${lang==='vi'?'Áp lực bắt buộc theo cấp độ':'Mandatory level pressure'}: −${money(extra)}</div>`:'';const shock=r?.monthly?.incomeCut||0;const note=shock?`<div class="income-shock">${lang==='vi'?'Thu nhập gián đoạn':'Income disruption'}: −${money(shock)} · ${lang==='vi'?'Lương thực nhận':'Salary received'} ${money(r.monthly.salary)}</div>`:'';const payments=r?.installments||[];return extraNote+note+(payments.length?`<div class="event-detail">${t('installmentsPaid')}: ${money(payments.reduce((a,p)=>a+p.amount-p.unpaid,0))}${payments.some(p=>p.unpaid>0)?` · ${t('unpaid')} ${money(payments.reduce((a,p)=>a+p.unpaid,0))}`:''}</div>`:'');}
function detail(r){let html=installmentDetail(r)+monthlyHTML(r,lang)+lessonHTML(r,lang);if(r.type==='expense'&&r.amount!==undefined)html+=`<div class="event-detail">${t('reserveUsed')}: ${money(r.fromReserve)}<br>${t('cashUsed')}: ${money(r.fromCash)}${r.sale>0?`<br><strong>${t('forced')} ${money(r.sale)}</strong>`:''}${r.unpaid>0?`<br>${t('unpaid')} ${money(r.unpaid)}`:''}</div>`;if(r.type==='learn'&&question(r.questionId))html+=`<div class="event-detail"><strong>${question(r.questionId)[lang][0]}</strong><br>${question(r.questionId)[lang][3]}</div>`;if(r.type==='market'&&r.changes?.length)html+=`<div class="event-detail">${r.changes.map(p=>`${p.id==='legacy'?CATEGORY_NAMES[lang].legacy:opportunity(p.id)[lang][0]}: ${signed(p.change)} (${Number((p.rate*100).toFixed(2))}%)`).join('<br>')}</div>`;return html;}

function circuit(){const g=receipt||state.gate;const text=lang==='vi'?{busy:'ĐANG ĐỌC X LAYER',ok:'ĐÃ XÁC MINH',error:'CHƯA XÁC MINH',wait:'Đang kiểm tra mạch trên X Layer…',fail:'Không đọc được mạch. Quyết định vừa thử chưa được áp dụng. Thử lại khi có kết nối; đầu tư mới đang khóa.',retry:'Kiểm tra lại',download:'Tải bằng chứng JSON',block:'Khối xác minh',detail:'Bằng chứng mạch',read:'Đọc miễn phí · Không ký ví · Tiền và nhật ký vẫn là giả lập'}:{busy:'READING X LAYER',ok:'VERIFIED',error:'UNVERIFIED',wait:'Checking the circuit on X Layer…',fail:'Circuit read unavailable. The attempted decision was not applied. Retry when connected; new investments are locked.',retry:'Check again',download:'Download proof JSON',block:'Verified block',detail:'Circuit evidence',read:'Free reads · No wallet signatures · Money and journal remain simulated'};
 $('#circuit').innerHTML=`<div class="circuit-heading"><span>${t('circuitTitle')}</span><span role="status">${chainBusy?text.busy:chainReady?text.ok:text.error}</span></div><p>${t('circuitText')}</p><div class="signal-row"><span>IN0 ${g.IN0}</span><span>IN1 ${g.IN1}</span><b>→ NAND →</b><span>OUT ${chainReady?g.OUT0:'?'}</span></div><p>${chainBusy?text.wait:chainError?text.fail:chainReady?t(g.OUT0===0?'gateStop':'gateContinue'):text.wait}</p><small>${t('circuitNote')}<br>${text.read}</small>${receipt&&chainReady?`<p>${text.block}: <a href="https://www.oklink.com/xlayer/block/${receipt.blockNumber}" target="_blank" rel="noopener noreferrer">${receipt.blockNumber}</a></p>`:''}<div class="proof-actions"><button data-proof="retry" ${chainBusy||rolling?'disabled':''}>${text.retry}</button><button data-proof="download" ${proof?'':'disabled'}>${text.download}</button></div>${proof?`<details><summary>${text.detail}</summary><p style="overflow-wrap:anywhere">${CIRCUIT.address}<br>Owner: ${proof.owner}<br>2 inputs · 1 output · 0 state · 3 gates</p><div class="signal-row">${proof.cases.map(c=>`<span>${c.IN0}${c.IN1} → ${c.OUT0}</span>`).join('')}</div><a href="https://www.oklink.com/xlayer/token/${CIRCUIT.address}/48" target="_blank" rel="noopener noreferrer">Circuit #48 ↗</a></details>`:''}`;
}

function history(){$('#history').innerHTML=state.history.length?state.history.map(r=>`<div class="history-row"><span>${t('monthWord')} ${r.month}</span><strong>${t('tile')[r.type]} · ${resultText(r)}</strong><em>${money(r.netWorth)}</em>${monthlyHTML(r,lang)}${lessonHTML(r,lang)}${r.type==='learn'&&question(r.questionId)?`<small class="journal-lesson">${question(r.questionId)[lang][0]}<br>${question(r.questionId)[lang][3]}</small>`:''}${r.installments?.length?`<small class="journal-lesson">${t('installmentsPaid')}: ${money(r.installments.reduce((a,p)=>a+p.amount-p.unpaid,0))}</small>`:''}</div>`).join(''):`<div class="empty">${t('empty')}</div>`;}
function render(){chrome();if(account){$('#saveLabel').textContent=serverError||((lang==='vi'?'Lưu theo ví · ':'Wallet save · ')+(serverBusy?(lang==='vi'?'Đang lưu…':'Saving…'):(lang==='vi'?'Đã đồng bộ':'Synced')));$('#progressReset').hidden=true;} renderHub();stats();$('#financialDashboard').innerHTML=financialDashboard(state,lang);board();management();decision();circuit();history();updateDecisionLab(state,lang);mountRiskPanel(state,lang,{source:account?'server-solo':'guest-local'});}
function random(max){const u=new Uint32Array(1);crypto.getRandomValues(u);const limit=Math.floor(0x100000000/max)*max;while(u[0]>=limit)crypto.getRandomValues(u);return u[0]%max;}
async function synchronize(candidate,full=false,nextHub=structuredClone(hub)){
 if(chainBusy)return false;chainBusy=true;chainError=false;render();
 try{
  if(full||!proof)proof=await verifyCircuit();
  const g=candidate.gate;
  receipt=await evaluateGate(g.IN0,g.IN1);
  candidate.gate={IN0:receipt.IN0,IN1:receipt.IN1,OUT0:receipt.OUT0};if(!full)recordGateProof(candidate,receipt);
  if(!account){settleRun(nextHub,candidate);trackSolo(state,candidate);state=candidate;hub=nextHub;persist();}chainReady=true;return true;
 }catch(error){console.warn('TapeOut read unavailable:',error.message);chainReady=false;chainError=true;return false;}
 finally{chainBusy=false;render();}
}
async function handle(action){
 if(rolling||chainBusy||serverBusy||booting)return;
 if(action==='reset'){$('#resetDialog').showModal();return;}
 if(account){await serverAction(action.startsWith('stage-')?'start':action,action.startsWith('stage-')?action.slice(6):state.difficulty);return;}
 if(action.startsWith('stage-')&&state.phase==='finished'){const candidate=createGame(action.slice(6)),nextHub=structuredClone(hub);if(!beginRun(nextHub,candidate,runId(),'challenge'))return;await synchronize(candidate,false,nextHub);$('#decision').scrollIntoView({block:'start',behavior:'smooth'});return;}
 const candidate=structuredClone(state),nextHub=structuredClone(hub);
 if(action==='start'){if(!beginRun(nextHub,candidate,runId(),selectedMode))return;}
 else if(action==='roll'){
  if(candidate.phase!=='ready')return;
  rolling=true;render();$('#board').classList.add('rolling');await new Promise(r=>setTimeout(r,650));
  prepareMove(candidate,random(6)+1,random(5)+1,random(0x100000000));rolling=false;
 }else if(action.startsWith('route-')){if(!chooseMove(candidate,Number(action.slice(6))))return;}else {if(action==='buy'&&!chainReady)return;if(!resolve(candidate,action))return;}
 await synchronize(candidate,false,nextHub);
 if(state.phase==='event')$('#decision').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});
}
document.addEventListener('click',e=>{
 const level=e.target.closest('[data-level]')?.dataset.level;const mode=e.target.closest('[data-mode]')?.dataset.mode;if(!state.started&&!chainBusy&&!rolling&&!serverBusy&&!booting){if(level&&Object.hasOwn(LEVELS,level)&&unlocked(hub,level)){state=createGame(level);persist();render();return;}if(mode==='challenge'||!account&&mode==='practice'&&state.difficulty==='easy'){selectedMode=mode;persist();render();return;}}
 const proofAction=e.target.closest('[data-proof]')?.dataset.proof;
 if(proofAction==='retry'&&!chainBusy&&!rolling)synchronize(structuredClone(state),true);
 if(proofAction==='download'&&proof){const blob=new Blob([JSON.stringify({...proof,latestGameplayRead:receipt},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='money-lab-circuit-48-proof.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const a=e.target.closest('[data-action]');if(a)handle(a.dataset.action);
 const m=e.target.closest('[data-manage]');if(m&&!rolling&&!chainBusy&&!serverBusy&&!booting){if(account){serverAction('manage-'+m.dataset.manage);return;}if(m.dataset.manage==='invest'&&!chainReady)return;const candidate=structuredClone(state);if(manage(candidate,m.dataset.manage))synchronize(candidate);}
});
['vi','en'].forEach(l=>$('#'+l).onclick=()=>{lang=l;try{localStorage.setItem('moneyLabLanguage',l);}catch{}render();});
$('#rulesButton').onclick=()=>$('#rules').showModal();$('#closeRules').onclick=()=>$('#rules').close();$('#resetButton').onclick=()=>{if(!chainBusy&&!rolling)$('#resetDialog').showModal();};$('#cancelReset').onclick=()=>$('#resetDialog').close();$('#confirmReset').onclick=()=>{if(chainBusy||rolling||serverBusy||booting)return;$('#resetDialog').close();if(account){serverAction('reset');return;}const nextHub=structuredClone(hub);abandonRun(nextHub,state);synchronize(createGame(unlocked(nextHub,state.difficulty)?state.difficulty:'easy'),false,nextHub);};
async function loadServer(){const d=await accountRequest('solo/state');state=d.game;hub=d.hub;serverRevision=d.revision;return d;}
async function serverAction(action,level=state.difficulty){if(serverBusy||booting)return;serverBusy=true;serverError='';chainBusy=true;render();try{const d=await accountRequest('solo/action',{action,level,revision:serverRevision,requestId:crypto.randomUUID()});state=d.game;hub=d.hub;serverRevision=d.revision;receipt=d.receipt||receipt;chainReady=true;chainError=false;}catch(e){serverError=accountMessage(e.message);try{await loadServer();}catch{}alert(serverError);}finally{serverBusy=false;chainBusy=false;render();}}
mountAccount();mountProgressReset();render();
accountReady.then(async()=>{try{if(account){selectedMode='challenge';await loadServer();}booting=false;await synchronize(structuredClone(state),true);}catch(e){serverError=accountMessage(e.message);booting=true;chainBusy=true;render();alert(serverError);}});


mountSoundtrack(()=>state);

mountAnalytics();
